---

Error boundary = class component. Hooks no catch render errors.

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ── Types ────────────────────────────────────────────────────────────────────

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

// ── Component ────────────────────────────────────────────────────────────────

class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };                          // triggers fallback render
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // default logger — swap for Sentry/Datadog/etc
    console.error("[ErrorBoundary] Caught error:", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);         // surface to parent if needed
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    // custom fallback provided
    if (fallback) return fallback(error, this.reset);

    // default fallback UI
    return <DefaultFallback error={error} reset={this.reset} />;
  }
}

// ── Default fallback UI ──────────────────────────────────────────────────────

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    background: "#fef2f2",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title:   { margin: "0 0 .5rem", color: "#b91c1c" },
  message: { fontSize: ".85rem", color: "#7f1d1d", whiteSpace: "pre-wrap" as const },
  button:  {
    marginTop: "1rem",
    padding: ".5rem 1.25rem",
    background: "#b91c1c",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
  },
} as const;

export default ErrorBoundary;
```

---

**Usage — basic**
```tsx
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>
```

**Usage — custom fallback**
```tsx
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
  onError={(error, info) => sentryCapture(error, info)}  // plug in real logger
>
  <MyComponent />
</ErrorBoundary>
```

---

**Key points:**

| Thing | Why |
|---|---|
| `getDerivedStateFromError` | Static — sets state to trigger re-render with fallback |
| `componentDidCatch` | Side effects only (logging). Never set state here |
| `reset` arrow fn | Clears error state → children remount fresh |
| `onError` prop | Decouple logging — caller injects Sentry/etc |
| `role="alert"` | Screen readers announce error |

**Retry caveat** — reset remount children. If error cause persist (bad prop, broken API), retry loop. Guard: pass `resetKeys` prop (like react-error-boundary lib) to reset only when specific deps change.
